cd /workspace/dev && python3 - <<'PYEOF'
import json, random, re, sys, os
sys.path.insert(0,'.')
import gen, run_tests
bad = 0
for seed in range(80):
    rng = random.Random(seed*17+3)
    request = gen.make_request(rng, big=(seed%4==3))
    proc = run_tests.run(request)
    text = proc.stdout.decode()
    if '-0.0' in text or 'NaN' in text or 'Infinity' in text or 'null' not in text and False:
        print('seed', seed, 'suspicious token')
        for m in re.finditer(r'.{30}-0\.0.{10}', text):
            print('   ', m.group(0))
        bad += 1
    # every number finite and in range
    resp = json.loads(text)
    def walk(v, path):
        if isinstance(v, dict):
            for k, x in v.items(): walk(x, path+'.'+k)
        elif isinstance(v, list):
            for i, x in enumerate(v): walk(x, path+'[%d]'%i)
        elif isinstance(v, float):
            assert v == v and abs(v) != float('inf'), (path, v)
            assert abs(v) <= 1e9, (path, v)
        elif isinstance(v, bool):
            raise AssertionError('boolean at '+path)
    walk(resp, '')
print('hygiene check done, suspicious:', bad)
PYEOF
